/* 第02轮：脚本、无字图像、文字层、排版独立；仅本机示意生成。 */
window.createCimoraComicModel=function(M,S){
  const clone=M.clone,blocked=c=>['running','paused'].includes(c.e.run?.status)?'请先停止当前制作批次':null;
  function ensure(c){if(c.c.kind==='episode')return c;for(const b of c.e.boards){b.comic??={revision:0,cast:[],scene:null,outfit:'',text:{speakerId:'',speakerName:'未指定',dialogue:b.dialogue||'',narration:'',sfx:''},images:[],adoptedId:null};}c.e.comicWidth??=800;return c;}
  const find=(c,id)=>{ensure(c);return c.e.boards.find(b=>b.id===id);};
  const assets=(c,type)=>S.state.assets.filter(a=>a.projectId===c.p.id&&a.type===type);
  function assetVersion(c,id,version){const a=S.state.assets.find(a=>a.projectId===c.p.id&&a.id===id);if(!a)return null;return clone(a.comicVersions?.find(v=>v.version===version)||(a.version===version?{id:a.id,version:a.version,name:a.name,desc:a.desc||'',outfit:a.outfit||'',type:a.type}:null));}
  function reference(c,id){const a=S.state.assets.find(a=>a.projectId===c.p.id&&a.id===id);return a?{id,version:a.version,snapshot:assetVersion(c,id,a.version)}:null;}
  function changed(c,b,event){b.comic.revision++;b.version++;c.e.reviewChecks=[false,false,false];M.log(c.e,event,b.title+' · 分格 v'+b.version+' · 旧图像与视频候选保留');M.save();}
  function editAsset(c,id,v){if(blocked(c))return blocked(c);let a=S.state.assets.find(a=>a.id===id&&a.projectId===c.p.id);if(!a)return '资产不存在';a.comicVersions??=[];if(!a.comicVersions.some(x=>x.version===a.version))a.comicVersions.push(assetVersion(c,id,a.version));a.version++;a.name=String(v.name||a.name);a.desc=String(v.desc??a.desc??'');a.outfit=String(v.outfit??a.outfit??'');a.comicVersions.push(assetVersion(c,id,a.version));M.log(c.e,'修正资产草案',a.name+' · v'+a.version+' · 旧分格引用不自动同步');M.save();return null;}
  function addAsset(c,v){if(blocked(c))return null;const a={id:S.id('comic-asset'),projectId:c.p.id,chapterIds:[],type:v.type==='场景'?'场景':'角色',name:String(v.name||'未命名草案'),desc:String(v.desc||''),outfit:String(v.outfit||''),art:v.type==='场景'?0:1,version:1,locked:false,draft:true};S.state.assets.push(a);c.p.assetIds??=[];c.p.assetIds.push(a.id);M.save();return a;}
  function seed(c){if(blocked(c))return blocked(c);ensure(c);let cast=assets(c,'角色')[0],scene=assets(c,'场景')[0];cast??=addAsset(c,{type:'角色',name:'角色A',desc:'占位角色草案，请按故事修正外观与姓名。',outfit:'服装待确认'});scene??=addAsset(c,{type:'场景',name:'场景A',desc:'占位场景草案，请按故事修正地点与光线。'});for(const b of c.e.boards){let did=false;if(!b.comic.cast.length){b.comic.cast=[reference(c,cast.id)];did=true;}if(!b.comic.scene){b.comic.scene=reference(c,scene.id);did=true;}if(did)changed(c,b,'建立角色场景草案引用');}M.save();return null;}
  function editPanel(c,id,v){if(blocked(c))return blocked(c);const b=find(c,id);if(!b)return '分格不存在';const q=b.comic;for(const k of ['title','action','shot'])if(k in v)b[k]=String(v[k]);if('castIds'in v)q.cast=v.castIds.map(id=>(!v.refreshRefs&&q.cast.find(r=>r.id===id))||reference(c,id)).filter(r=>r?.snapshot?.type==='角色');if('sceneId'in v)q.scene=!v.refreshRefs&&q.scene?.id===v.sceneId?q.scene:reference(c,v.sceneId);if('outfit'in v)q.outfit=String(v.outfit);if('dialogue'in v){b.dialogue=String(v.dialogue);q.text.dialogue=b.dialogue;}for(const k of ['narration','sfx'])if(k in v)q.text[k]=String(v[k]);if('speakerId'in v){q.text.speakerId=v.speakerId||'';q.text.speakerName=q.cast.find(r=>r.id===v.speakerId)?.snapshot.name||'未指定';}if(q.text.speakerId&&!q.cast.some(r=>r.id===q.text.speakerId)){q.text.speakerId='';q.text.speakerName='未指定';}changed(c,b,'保存分格脚本与文字层');return null;}
  function imageInput(b){return clone({action:b.action,shot:b.shot,cast:b.comic.cast,scene:b.comic.scene,outfit:b.comic.outfit});}
  function generate(c,id,options={}){if(blocked(c))return {error:blocked(c)};const b=find(c,id);if(!b)return {error:'分格不存在'};const q=b.comic,version=q.images.length+1,candidate={id:S.id('comic-image'),version,status:options.fail?'failed':'ready',art:(Number(b.art||0)+version-1)%10,input:imageInput(b),prototype:true,createdAt:new Date().toISOString(),error:options.fail?'模拟供应商失败；旧采用版未替换。':''};q.images.unshift(candidate);M.log(c.e,options.fail?'单格图像模拟失败':'单格图像候选已保存',b.title+' · 图像 v'+version+' · 未自动采用');M.save();return {candidate};}
  function adopted(b){return b.comic?.images.find(x=>x.id===b.comic.adoptedId&&x.status==='ready')||null;}
  function adopt(c,id,imageId){if(blocked(c))return blocked(c);const b=find(c,id),image=b?.comic.images.find(x=>x.id===imageId);if(!image||image.status!=='ready')return '失败或失效候选不能采用';b.comic.adoptedId=image.id;b.art=image.art;b.approved=true;changed(c,b,'显式采用单格图像');return null;}
  function layout(c,v){if(blocked(c))return blocked(c);if('gap'in v)c.e.comicGap=Math.max(8,Math.min(96,Number(v.gap)||20));if('width'in v)c.e.comicWidth=Math.max(480,Math.min(1080,Number(v.width)||800));c.e.reviewChecks=[false,false,false];M.save();return null;}
  function source(b){if(!b.comic?.revision)return null;const q=b.comic;return clone({baseImage:adopted(b),text:{...q.text,dialogue:b.dialogue||''},cast:q.cast,scene:q.scene,outfit:q.outfit});}
  function documentData(c){ensure(c);return clone({title:c.p.name,chapter:c.c.title,gap:c.e.comicGap,width:c.e.comicWidth,prototype:true,panels:c.e.boards.map(b=>({id:b.id,title:b.title,baseImage:adopted(b),text:{...b.comic.text,dialogue:b.dialogue||''},cast:b.comic.cast,scene:b.comic.scene}))});}
  M.comic={ensure,find,assets,assetVersion,addAsset,editAsset,seed,editPanel,generate,adopt,adopted,layout,source,document:documentData,imageInput,blocked};return M;
};
